ium'][$plan['code']]??$plan['name'])?><?php if(!empty($plan['prices']['monthly']['amount'])):?> · $<?=number_format((float)$plan['prices']['monthly']['amount'],0,',','.') ?>/mes<?php if(!empty($plan['prices']['annual']['amount'])):?> · $<?=number_format((float)$plan['prices']['annual']['amount'],0,',','.') ?>/año<?php endif ?><?php endif ?></option><?php endforeach ?></select></label><label>Frecuencia<select name="billing_frequency"><option value="monthly" <?=($purchaseForBusiness['period']??$onboardingChoice['billing_frequency']??$initialRequest['billing_frequency']??$currentSubscription['billing_frequency']??'monthly')==='monthly'?'selected':''?>>Mensual</option><option value="quarterly" <?=($purchaseForBusiness['period']??$onboardingChoice['billing_frequency']??$initialRequest['billing_frequency']??$currentSubscription['billing_frequency']??'monthly')==='quarterly'?'selected':''?>>Trimestral</option><option value="semiannual" <?=($purchaseForBusiness['period']??$onboardingChoice['billing_frequency']??$initialRequest['billing_frequency']??$currentSubscription['billing_frequency']??'monthly')==='semiannual'?'selected':''?>>Semestral</option><option value="annual" <?=($purchaseForBusiness['period']??$onboardingChoice['billing_frequency']??$initialRequest['billing_frequency']??$currentSubscription['billing_frequency']??'monthly')==='annual'?'selected':''?>>Anual</option></select></label><div class="notice account-payment-quote">Valor de esta elección: <strong data-price-output>—</strong><small data-plan-requirements-output></small></div><?php if($addonService->eligibleBusiness((int)$business['id'])){$operatorExperiences=$addonService->options((int)$business['destination_id']);$activeOperator=$currentSubscription?$addonService->forSubscription((int)$currentSubscription['id']):null;$selectedOperatorExperienceId=(int)($_POST['operator_experience_id']??$purchaseForBusiness['experience_id']??$activeOperator['experience_id']??0);require __DIR__.'/operator-addon-choice.php';} ?><?php require __DIR__.'/payment-instructions.php'; ?><label class="wide">Soporte de pago · PDF, JPG, PNG o WebP · máximo 8 MB<input type="file" name="payment_proof" accept="application/pdf,image/jpeg,image/png,image/webp"></label><fieldset class="wide payment-transaction-fields" data-payment-transaction><legend>Datos de la transacción</legend><p>Referencia de esta solicitud: <strong><?=esc($checkoutReference)?></strong>. Escríbela en el concepto de la transferencia si tu banco lo permite. Si no permite concepto, igual puedes enviar el comprobante.</p><div class="destination-form-grid"><label>Número de transacción o autorización<input name="payment_reference" maxlength="140" required value="<?=esc($_POST['payment_reference']??'')?>"><small>Copia el número que aparece en tu comprobante; es distinto de la referencia de solicitud.</small></label><label>Fecha del pago<input type="date" name="transaction_date" max="<?=date('Y-m-d')?>" required value="<?=esc($_POST['transaction_date']??'')?>"></label><label>Valor efectivamente pagado · COP<input type="number" name="paid_amount" min="0.01" step="0.01" required value="<?=esc($_POST['paid_amount']??'')?>"><small>Sin puntos de miles. Registra lo que transferiste, aunque difiera del importe esperado.</small></label><label>Medio utilizado<select name="payment_method" required><option value="">Selecciona</option><?php foreach(['breb'=>'Llave Bre-B','transfer'=>'Transferencia bancaria','qr'=>'QR','other'=>'Otro'] as $code=>$label):?><option value="<?=$code?>" <?=($_POST['payment_method']??'')===$code?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><label class="wide">Banco o aplicación de origen<input name="source_bank" maxlength="120" required value="<?=esc($_POST['source_bank']??'')?>"><small>No incluyas claves ni el número completo de tu cuenta.</small></label></div></fieldset></div><button class="pill compact" type="submit">Enviar suscripción y soporte</button></form><?php endforeach ?><?php endif ?></section>
<?php $cancelBusinesses=array_filter($businesses,static fn($business)=>($business['subscription_status']??'')==='active'&&($business['plan_code']??'free')!=='free');if($finance->ready()&&$businesses):?><section class="destination-admin-list"><h2>Solicitar cancelación o no renovación</h2><p>Registra tu solicitud para que el equipo la atienda. El período pagado conserva su vigencia mientras se revisa; este envío no ejecuta devoluciones ni cancela pagos externos.</p><?php if(isset($_GET['cancelacion'])):?><p role="status">Solicitud registrada. Puedes consultar su estado aquí.</p><?php endif ?><?php if($cancelBusinesses):?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="cancel_request"><label>Negocio<select name="business_id" required><?php foreach($cancelBusinesses as $business):?><option value="<?=esc($business['id'])?>"><?=esc($business['display_name'])?></option><?php endforeach ?></select></label><label>Motivo<select name="reason_code"><?php foreach(OperatingFinanceService::REASONS as $code=>$label):?><option value="<?=esc($code)?>"><?=esc($label)?></option><?php endforeach ?></select></label><label>Detalle opcional<textarea name="reason_text" maxlength="1000"></textarea></label><button class="pill">Enviar solicitud</button></form><?php else:?><p>No tienes una suscripción paga activa para solicitar su cancelación.</p><?php endif ?><?php $cancellationQuery=db()->prepare('SELECT reason_code,status,created_at,review_note FROM subscription_cancellation_requests WHERE account_id=? AND business_id=? ORDER BY id DESC LIMIT 30');$cancellationQuery->execute([(int)$account['id'],$selectedBusinessId]);foreach($cancellationQuery as $request):?><p><?=esc($request['created_at'])?> · <?=esc(OperatingFinanceService::REASONS[$request['reason_code']]??$request['reason_code'])?> · <?=esc($request['status']==='pending'?'Pendiente de atención':'Atendida')?><?php if($request['review_note']):?><br><?=esc($request['review_note'])?><?php endif ?></p><?php endforeach ?></section><?php endif ?>
<section class="account-next-steps"><h2>Tu vista previa y publicación</h2><?php if($selectedBusinessId):?><p><a class="pill" href="/business/editorial.php?business=<?=$selectedBusinessId?>">Completar contenido y ver mi borrador</a></p><?php endif ?><p>Puedes revisar cómo se verá tu negocio con tus datos y fotografías originales, también después de enviar el pago. Luego prepararemos las imágenes y traducciones y te enviaremos por correo la versión final para aprobarla o solicitar cambios.</p><p>Enviar una suscripción no confirma el pago ni publica el negocio. Tras validar el soporte y la información, el equipo preparará y aprobará el borrador por separado.</p></section><?php endif ?></main><script src="<?=esc(site_path('/assets/business-subscriptions.js?v=prorated-changes-1'))?>" defer></script><script src="/assets/account-files.js?v=1" defer></script><?php require __DIR__.'/qr-dialog.php'; ?><script src="/assets/vendor/qrcodegen-v1.8.0.js" defer></script><script src="/assets/business-qr.js" defer></script></body></html>
